    f = sech(c + d*x)/(a + b*sinh(c + d*x))
    F = a*atan(sinh(c + d*x))/(d*(a**2 + b**2)) + b*log(a + b*sinh(c + d*x))/(d*(a**2 + b**2)) - b*log(cosh(c + d*x))/(d*(a**2 + b**2))
    assert integrate(f, x) == F


