def test_integrate_6_Hyperbolic_functions_6_1_Hyperbolic_sine_6_1_1_c_plus_d_x_pow_m_a_plus_b_sinh_pow_n_389():
    f = tanh(c + d*x)**2*sech(c + d*x)/(a + b*sinh(c + d*x))
    F = a**2*b*log(a + b*sinh(c + d*x))/(d*(a**2 + b**2)**2) - a**2*b*log(cosh(c + d*x))/(d*(a**2 + b**2)**2) + a*(a**2 - b**2)*atan(sinh(c + d*x))/(2*d*(a**2 + b**2)**2) - (a*sinh(c + d*x) + b)*sech(c + d*x)**2/(d*(2*a**2 + 2*b**2))
    assert integrate(f, x) == F


